import { onMounted, ref, nextTick } from 'vue';
export default {  
  setup() {
    const count = ref(0);
    const $ = jQuery
    onMounted(async () => {
      await nextTick(); // 等待下一个DOM更新循环结束  
    });
    function swiperFn(){
        $(document).ready(function () {
            var swiper = new Swiper(".client-say-home-3", {
                slidesPerView: 1,
                loop: true,
                navigation: {
